"""Wire the product-purpose view into the canonical metamodel and existing application."""
from pathlib import Path
import sys,yaml
R=Path(__file__).resolve().parents[2];sys.path[:0]=[str(R/'tools'),str(R/'tmp/model-deps')]
def read(p):return yaml.safe_load((R/p).read_text(encoding='utf-8'))
def write(p,d):(R/p).write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False,width=110),encoding='utf-8')
doc=read('source/fonctions-produit-core.yaml');doc['reading']['process_reservation']='L’estimation retenue de Process Management ne démontre pas la couverture des studios, du portail de tâches, du Process Mining et des tableaux de bord précisés. Le contrôle COSMIC doit reprendre le même périmètre complet.';write('source/fonctions-produit-core.yaml',doc)
schema=read('source/schema-fonctions-produit-core.yaml');allocation=schema['properties']['allocations']['items'];allocation['properties']['basis']=dict(type='string',minLength=1);allocation['required'].append('basis');write('source/schema-fonctions-produit-core.yaml',schema)
p='source/fondamentaux.yaml';d=read(p);m=d['estimation_model'];ids={o['id'] for o in m['objects']}
for id,label,attributes in [('product_purpose','Finalité métier ou IT des fonctions du produit',['id','label','definition']),('professional_function','Fonction professionnelle du produit hors hiérarchie métier native',['id','purpose','boundary','capability_refs','dependencies','evidence','existing_funding_to_review','additional_effort_status']),('purpose_partition','Ventilation des efforts adoptés par finalité',['unit_id','evidence','basis','role_effort_by_purpose','unallocated_effort','unallocated_cost'])]:
 assert id not in ids;m['objects'].append(dict(id=id,label=label,owner='source/fonctions-produit-core.yaml',attributes=attributes))
unit=next(o for o in m['objects'] if o['id']=='evaluation_unit');unit['attributes'].extend(['professional_function_refs','purpose_partition_status'])
for id,src,dst,card,meaning in [('function_purpose','professional_function','product_purpose','many-to-one','La finalité du travail est indépendante des rôles du projet et des couches techniques.'),('function_evidence','professional_function','market_reference','many-to-many','Comparer les fonctions administratives et professionnelles des suites, sans déduire leur absence d’un fichier manquant.'),('function_funding','professional_function','mechanism','many-to-many','Rapprocher les travaux déjà financés avant toute charge complémentaire ; la présence de code ne prouve pas la complétude du financement.'),('purpose_of_adopted_unit','purpose_partition','evaluation_unit','many-to-one','Ventiler une décision adoptée sans changer ses JH, rôles, prix ni calendrier.'),('purpose_share','purpose_partition','product_purpose','many-to-many','Une part déclarée de JH par rôle compte une fois ; une part inconnue reste non ventilée, sans devenir zéro.')]:m['relations'].append(dict(id=id,source=src,target=dst,cardinality=card,meaning=meaning))
for id,title,unit in [('purpose_unallocated_jh','JH adoptés non encore ventilés entre métier et IT','JH'),('purpose_unallocated_cost','Coût adopté non encore ventilé entre métier et IT','EUR HT')]:
 m['rules'].append(dict(id=id,title=title,expression='total - business - it',variables=dict(total='Total adopté sur la même assiette',business='Part métier explicitement attribuée',it='Part IT explicitement attribuée'),unit=unit,kind='arithmetic',note='Les parts attribuées ne sont pas une nouvelle estimation. Leur somme et le non ventilé doivent conserver le total et chaque rôle.',domains={k:dict(minimum=0) for k in ['total','business','it']}))
m['rules'].append(dict(id='product_purpose_partition',title='Ventilation des fonctions métier et IT du produit',expression='Contrôler les fonctions professionnelles et leurs preuves ; ventiler les JH adoptés par rôles et finalités seulement sur une attribution justifiée ; conserver le reste non ventilé et le complément requis inconnu.',variables=dict(adopted_units='Décisions adoptées et valorisées',declared_allocations='Attributions étayées en JH par rôle',professional_functions='Fonctions du produit et réutilisation à qualifier'),unit='Ventilation des JH et EUR HT adoptés, sans nouveau budget',kind='algorithm',note='La cartographie native reste inchangée. Runtime et outils métier sont distincts des fonctions IT transverses ; un rôle QA ou DevOps ne constitue pas une catégorie fonctionnelle.'))
next(i for i in m['implementations'] if i['path']=='tools/estimation_calculation.py')['rules'].extend(['purpose_unallocated_jh','purpose_unallocated_cost']);m['implementations'].append(dict(path='tools/core_product_scope.py',rules=['product_purpose_partition']))
m['invariants'].extend(['La complétude du produit inclut les fonctions professionnelles IT absentes de la cartographie métier ; aucune nouvelle capacité native n’est créée.','Les coûts métier, IT et non ventilés partitionnent les seuls travaux adoptés. Les compléments inconnus restent null ; ils ne sont ni inclus par défaut ni mis à zéro.','Une ventilation par finalité conserve les JH de chaque rôle et les tarifs de chaque unité. Les familles déjà adoptées ne sont pas estimées à nouveau par ce partage.'])
d['estimation']['note']+=' La cartographie métier ne couvre pas toutes les fonctions IT nécessaires au produit. Une lecture distincte sépare runtime et outils métier des compléments IT ; les travaux déjà mêlés aux décisions restent non ventilés tant que leur attribution n’est pas justifiée.';write(p,d)
p=R/'tools/study_app.py';s=p.read_text(encoding='utf-8');s=s.replace('from delivery_readiness import build_delivery_readiness','from delivery_readiness import build_delivery_readiness\nfrom core_product_scope import build_core_product_scope, dependencies as core_product_dependencies',1);s=s.replace("files=set(paths)|set(self.data['empreintes'])","files=set(paths)|set(self.data['empreintes'])|core_product_dependencies()",1);anchor="content['economic_evaluations'] = build_economic_evaluations(self.baseline, content, self.glossary, self.document_path)";assert anchor in s;s=s.replace(anchor,anchor+"\n        content['core_product_scope'] = build_core_product_scope(self.economic)",1);s=s.replace("'core_evaluation':self._essential_core_evaluation(unit_details=False)} if essential","'core_evaluation':self._essential_core_evaluation(unit_details=False),\n                 'core_product_scope':deepcopy(self.content['core_product_scope'])} if essential",1);p.write_text(s,encoding='utf-8')
p=R/'tools/study_snapshot.py';s=p.read_text(encoding='utf-8');assert "'core_product_scope.py'" not in s;s=s.replace("'economic_reading.py'","'economic_reading.py','core_product_scope.py'",1);p.write_text(s,encoding='utf-8')
p='source/statut-evaluation.yaml';d=read(p);d['core']['title']='Construction du produit : estimations adoptées, complétude à vérifier';d['core']['summary']='**Les capacités Java/Spring disposent d’estimations adoptées. La complétude du produit reste à instruire : studios, pilotage et fonctions IT professionnelles.** La lecture métier/IT ne répartit pas arbitrairement ces charges. .NET et Rust restent à réestimer.';d['core']['text']='**Les décisions adoptées restent conservées.** Elles ne constituent pas encore un chiffrage complet des studios métier et des fonctions IT complémentaires. La ventilation métier/IT doit distinguer les travaux déjà financés, leur réutilisation et les compléments à estimer. Les montants non déterminés ne valent pas zéro. .NET et Rust restent à réestimer ; le calendrier global demeure provisoire et les simulations sont conservées.';write(p,d)
p='source/methode-evaluation-core.yaml';d=read(p);first=d['sections'][0];first['blocks'].append(dict(kind='callout',title='Compléter le périmètre du produit professionnel',text='Le référentiel des capacités est un entrant métier immuable. Il ne décrit pas tous les outils d’administration, de robustesse et de sécurité. Inventorier séparément ces fonctions dans fonctions-produit-core.yaml, les rapprocher des quatre suites et du financement existant. Séparer runtime et outils métier des compléments IT ; ne pas convertir la répartition des rôles en répartition fonctionnelle. Une fonction non chiffrée reste inconnue, sans budget nul présumé.'));write(p,d)
p=R/'source/README.md';s=p.read_text(encoding='utf-8');anchor='| Estimations Core retenues |';row='| Fonctions professionnelles et finalités métier/IT | `fonctions-produit-core.yaml`, `schema-fonctions-produit-core.yaml`, `tools/core_product_scope.py` | Inventaire séparé de la cartographie native, preuves OSS et rapprochement des financements. Les attributions étayées en JH par rôle partitionnent les décisions adoptées ; les parts non justifiées restent non ventilées et les compléments inconnus. Les objets et règles sont définis dans le métamodèle unique. |\n';assert anchor in s;s=s.replace(anchor,row+anchor,1);p.write_text(s,encoding='utf-8')
p=R/'AGENTS.md';s=p.read_text(encoding='utf-8');anchor='- Les anciennes grilles ordinales';note='- Le périmètre professionnel du produit est dans `source/fonctions-produit-core.yaml`, séparé de la cartographie native. La finalité métier/IT est indépendante des rôles et couches techniques. Les estimations adoptées ne sont pas intégralement du runtime métier : conserver le non ventilé tant qu’une attribution justifiée en JH par rôle n’est pas déclarée. Ne jamais afficher zéro pour un complément IT non estimé.\n';assert anchor in s;s=s.replace(anchor,note+anchor,1);p.write_text(s,encoding='utf-8')
print('Canonical product scope and purpose partition wired; adopted estimates untouched')
